using Bancoficticio.Transferencias.Adapters.In.Rest;
using Bancoficticio.Transferencias.Domain.Error;
using Bancoficticio.Transferencias.Domain.Port;

namespace Bancoficticio.Transferencias.Application;

/// <summary>Application service of the use case RealizarTransferencia (legacy TRANSFERENCIA, btnTransferir_Click).</summary>
public sealed class RealizarTransferenciaService(CuentaRepository cuentas, TransferenciaRepository transferencias)
{
    public RealizarTransferenciaResponse Execute(RealizarTransferenciaRequest request)
    {
        // Legacy: Text.Trim() (a WebForms Text property is never null) and decimal.Parse(txtMonto.Text).
        string origen = (request.Origen ?? string.Empty).Trim();
        string destino = (request.Destino ?? string.Empty).Trim();
        decimal monto = request.Monto ?? throw new ArgumentNullException(nameof(request.Monto));
        string? tipo = request.Tipo;

        // RULE-005: before any database access.
        if (origen == destino)
        {
            throw new BusinessError("CUENTA_DESTINO_IGUAL", "-1", "LA CUENTA DESTINO ES LA MISMA");
        }

        // RULE-006
        var cuentaOrigen = cuentas.FindByNumero(origen);
        if (cuentaOrigen is null)
        {
            throw new BusinessError("CUENTA_ORIGEN_NO_EXISTE", "-1", "CUENTA ORIGEN NO EXISTE");
        }
        string? estado = cuentaOrigen.Estado;
        decimal saldo = cuentaOrigen.Saldo!.Value;
        if (estado != "A")
        {
            throw new BusinessError("CUENTA_ORIGEN_INACTIVA", "-1", "CUENTA ORIGEN INACTIVA");
        }

        // RULE-007
        if (!cuentas.ExistsActive(destino))
        {
            throw new BusinessError("CUENTA_DESTINO_NO_EXISTE", "-1", "CUENTA DESTINO NO EXISTE");
        }

        // RULE-008
        decimal comision = Calcular(monto, tipo);
        if (saldo < monto + comision)
        {
            throw new BusinessError("SALDO_INSUFICIENTE", "-1", "SALDO INSUFICIENTE");
        }

        // RULE-009
        cuentas.Debit(origen, monto + comision);
        cuentas.Credit(destino, monto);

        // RULE-010
        int numero = transferencias.NextNumero();
        transferencias.Insert(numero, origen, destino, monto, comision, tipo);

        return new RealizarTransferenciaResponse(numero, comision, "TRANSFERENCIA REALIZADA");
    }

    // Legacy ComisionService.Calcular, preserved exactly.
    private static decimal Calcular(decimal monto, string? tipo)
    {
        decimal comision = monto <= 1000m ? 0.50m : Math.Round(monto * 0.001m, 2, MidpointRounding.AwayFromZero);
        if (comision > 5.00m)
        {
            comision = 5.00m;
        }
        if (tipo == "INM")
        {
            comision += 1.00m;
        }
        return comision;
    }
}

