using Xunit;

namespace Bancoficticio.Transferencias.Tests;

public sealed class RealizarTransferenciaServiceTests
{
    // ---------- fakes ----------

    private sealed class FakeCuentas(List<string> calls) : CuentaRepository
    {
        public Dictionary<string, Cuenta> Accounts { get; } = new();
        public List<string?> FindCalls { get; } = new();
        public List<string?> ExistsActiveCalls { get; } = new();
        public List<(string? Numero, decimal? Valor)> Debits { get; } = new();
        public List<(string? Numero, decimal? Valor)> Credits { get; } = new();

        public Cuenta? FindByNumero(string? numero)
        {
            calls.Add("Cuentas.FindByNumero");
            FindCalls.Add(numero);
            return numero is not null && Accounts.TryGetValue(numero, out var c) ? c : null;
        }

        public bool ExistsActive(string? numero)
        {
            calls.Add("Cuentas.ExistsActive");
            ExistsActiveCalls.Add(numero);
            return numero is not null && Accounts.TryGetValue(numero, out var c) && c.Estado == "A";
        }

        public void Debit(string? numero, decimal? valor)
        {
            calls.Add("Cuentas.Debit");
            Debits.Add((numero, valor));
        }

        public void Credit(string? numero, decimal? valor)
        {
            calls.Add("Cuentas.Credit");
            Credits.Add((numero, valor));
        }
    }

    private sealed class FakeTransferencias(List<string> calls) : TransferenciaRepository
    {
        public int Next { get; set; } = 1;
        public List<Transferencia> Inserted { get; } = new();

        public int NextNumero()
        {
            calls.Add("Transferencias.NextNumero");
            return Next;
        }

        public void Insert(int? numero, string? origen, string? destino, decimal? monto, decimal? comision, string? tipo)
        {
            calls.Add("Transferencias.Insert");
            Inserted.Add(new Transferencia(numero, origen, destino, monto, comision, tipo));
        }

        public Transferencia? FindByNumero(int? numero)
        {
            calls.Add("Transferencias.FindByNumero");
            return null;
        }
    }

    private sealed class Fixture
    {
        public List<string> Calls { get; } = new();
        public FakeCuentas Cuentas { get; }
        public FakeTransferencias Transferencias { get; }
        public RealizarTransferenciaService Service { get; }

        public Fixture()
        {
            Cuentas = new FakeCuentas(Calls);
            Transferencias = new FakeTransferencias(Calls);
            Service = new RealizarTransferenciaService(Cuentas, Transferencias);
        }

        public Fixture WithAccount(string numero, string estado, decimal saldo)
        {
            Cuentas.Accounts[numero] = new Cuenta(numero, estado, saldo);
            return this;
        }

        public void AssertNoWrites()
        {
            Assert.Empty(Cuentas.Debits);
            Assert.Empty(Cuentas.Credits);
            Assert.Empty(Transferencias.Inserted);
            Assert.DoesNotContain("Transferencias.NextNumero", Calls);
        }
    }

    private static RealizarTransferenciaRequest Req(string? origen, string? destino, decimal? monto, string? tipo)
        => new(origen, destino, monto, tipo);

    private static void AssertError(BusinessError error, string code, string message)
    {
        Assert.Equal(code, error.Code);
        Assert.Equal("-1", error.LegacyCode);
        Assert.Equal(message, error.Message);
    }

    // Executes a successful transfer and returns the commission debited on top of the amount.
    private static (Fixture Fx, RealizarTransferenciaResponse Response) RunOk(decimal monto, string? tipo, decimal saldo = 1000000m)
    {
        var fx = new Fixture()
            .WithAccount("1001", "A", saldo)
            .WithAccount("2002", "A", 50.00m);
        var response = fx.Service.Execute(Req("1001", "2002", monto, tipo));
        return (fx, response);
