    // ---------- RULE-005 ----------

    [Fact]
    public void Rule005_SameAccount_RejectsWithoutAnyDatabaseAccess()
    {
        var fx = new Fixture().WithAccount("1001", "A", 500.00m);

        var error = Assert.Throws<BusinessError>(() => fx.Service.Execute(Req("1001", "1001", 100.00m, "ORD")));

        AssertError(error, "CUENTA_DESTINO_IGUAL", "LA CUENTA DESTINO ES LA MISMA");
